// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO;
using Shared.DTO.Customer;
using Shared.DTO.Departments;
using Shared.DTO.Employee;
using Shared.DTO.WorkOrder;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.WorkOrder
{
    public partial class Create
    {
        WorkOrderDto workOrder { get; set; } = new WorkOrderDto();

        private List<SelectOptionDto>? DepartmentOptions = new List<SelectOptionDto>();

        private List<SelectOptionDto>? CustomerOptions = new List<SelectOptionDto>();

        private List<SelectOptionDto>? EmployeeOptions = new List<SelectOptionDto>();

        private List<SelectOptionDto>? ProductOptions = new List<SelectOptionDto>();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected override async Task OnInitializedAsync()
        {
            DepartmentOptions = await Http.GetFromJsonAsync<List<SelectOptionDto>>("api/Departments/getselectoption");
            try
            {
                CustomerOptions = await Http.GetFromJsonAsync<List<SelectOptionDto>>("api/Customers/getselectoption");
            }
            catch { }

        }

        protected async Task GetItmeFrmoDepartment()
        {
            EmployeeOptions = await Http.GetFromJsonAsync<List<SelectOptionDto>>("api/Employees/getSelectoptionByDepartment/"+ workOrder.Department.Uuid);
            ProductOptions = await Http.GetFromJsonAsync<List<SelectOptionDto>>("api/Products/getSelectoptionByDepartment/" + workOrder.Department.Uuid);


        }


        protected async Task AddWorkOrder()
        {
            var response = await Http.PostAsJsonAsync("api/WorkOrders", workOrder);
            if (response.IsSuccessStatusCode)
            {
                NavMan.NavigateTo("/WorkOrder");
            }
            else
            {
                Console.WriteLine($"Error >> {response.ReasonPhrase}");
            }

        }
    }
}
